list_trash.code:
final response = await client.trash.listTrash(queryParams: {
  'type': 'Category',
  'search': 'spring',
  'sort': 'name',
  'order': 'asc',
  'limit': 20,
});
final body = response.map as Map;
for (final item in body['items'] as List) {
  print('${(item as Map)['id']} ${item['type']} ${item['name']}');
}
print((body['pagination'] as Map)['total']);

