bulk_restore_trash.code:
final response = await client.trash.bulkRestoreTrash({
  'items': [
    {'type': 'Category', 'id': 1234},
    {'type': 'BlogPost', 'id': 99},
  ],
});
final result = response.map as Map;
for (final item in result['restored'] as List) {
  print('${(item as Map)['type']} ${item['id']} ${item['name']}');
}
for (final failure in result['failed'] as List) {
  print('${(failure as Map)['id']} ${failure['code']} ${failure['message']}');
}

